// src/v3/film scene registry (static: every panel imported by name; generated by scripts/g5_scaffold.py, the engine
// lane owns it). A panel module default-exports its scene (React.FC, no props) and may export `Wiper`
// (WiperComponent, for a foreground-wipe OUT of it) and `captionTone` (ToneKey[], scene-local t: overrides the
// panel's scenes.json captionTone, so a lane sets its own caption tone without touching a shared file).
import type React from 'react';
import type {ToneKey, WiperProps} from '../../../lib/Film';

import * as O1 from './O1';
import * as S4 from './S4';
import * as S5 from './S5';
import * as S6 from './S6';
import * as S7 from './S7';
import * as S8 from './S8';
import * as S9 from './S9';
import * as S10 from './S10';
import * as S11 from './S11';
import * as S12 from './S12';
import * as S13 from './S13';
import * as S14 from './S14';
import * as S15 from './S15';
import * as S16 from './S16';

type PanelModule = {default: React.FC; Wiper?: React.FC<WiperProps>; captionTone?: ToneKey[]};
const PANELS: Record<string, PanelModule> = {"O1": O1, "S4": S4, "S5": S5, "S6": S6, "S7": S7, "S8": S8, "S9": S9, "S10": S10, "S11": S11, "S12": S12, "S13": S13, "S14": S14, "S15": S15, "S16": S16};

export const sceneComponents: Record<string, React.FC> = {};
export const sceneWipers: Record<string, React.FC<WiperProps>> = {};
export const sceneTones: Record<string, ToneKey[]> = {};
for (const [id, m] of Object.entries(PANELS)) {
  sceneComponents[id] = m.default;
  if (typeof m.Wiper === 'function') sceneWipers[id] = m.Wiper;
  if (Array.isArray(m.captionTone) && m.captionTone.length) sceneTones[id] = m.captionTone;
}
